void HTreeClass::Scale(float factor)
{
	if (factor != 1.0f) {
		for (int bone = 0; bone < NumPivots; bone++) {
			float *translation = &Pivot[bone].Base.Translation.X;
			translation[0] = translation[0] * factor;
			translation[1] = translation[1] * factor;
			translation[2] = translation[2] * factor;
		}
		ScaleFactor *= factor;
	}
}

