// FUNCTION: BFME2 0x001614F0 size=526 name=?read_pivots@HTreeClass@@AAE_NAAVChunkLoadClass@@_N@Z evidence=N:ledger tier=B hypothesis:K
bool HTreeClass::read_pivots(ChunkLoadClass &loader, bool pre30)
{
	// Files older than 3.0 have no root pivot: make one at index 0 and shift every parent index by one.
	int first = 0;
	if (pre30) {
		Pivot->Index = 0;
		Pivot->Parent = 0;
		Pivot->Base.Make_Identity();
		Pivot->Current.Make_Identity();
		Pivot->IsVisible = true;
		Pivot->Fade = 1.0f;
		strcpy(Pivot->Name, "RootTransform");
		first = 1;
	}

	for (int index = first; index < NumPivots; index++) {
		W3dPivotStruct piv;
		if (loader.Read(&piv, sizeof(piv)) != sizeof(piv)) {
			return false;
		}
		memcpy(Pivot[index].Name, piv.Name, sizeof(Pivot[index].Name));
		Pivot[index].Index = index;
		Pivot[index].Base.Translation.Set(piv.Translation.X, piv.Translation.Y, piv.Translation.Z);
		Pivot[index].Base.Rotation.Set(piv.Rotation.Q[0], piv.Rotation.Q[1], piv.Rotation.Q[2], piv.Rotation.Q[3]);

		if (pre30) {
			piv.ParentIdx++;
		}
		if (piv.ParentIdx == -1) {
			Pivot[index].Parent = 0;
		} else {
			Pivot[index].Parent = &Pivot[piv.ParentIdx];
		}
	}

	Pivot[0].Current.Make_Identity();
	Pivot[0].IsVisible = true;
	Pivot[0].Fade = 1.0f;
	return true;
}

