// FUNCTION: BFME2 0x00162030 size=48 name=?Is_Bone_Captured@HTreeClass@@QBE_NH@Z evidence=N:ledger tier=B hypothesis:K
bool HTreeClass::Is_Bone_Captured(int boneindex) const
{
	_STL::vector<HTreeCapture>::const_iterator capture = CaptureList.begin();
	while (capture != CaptureList.end() && capture->BoneIndex < boneindex) {
		capture++;
	}
	return capture != CaptureList.end() && capture->BoneIndex == boneindex;
}

// FUNCTION: BFME2 0x00162060 size=112 name=?Control_Bone@HTreeClass@@QAEXHABVMatrix3D@@_N@Z evidence=N:ledger tier=B hypothesis:K
void HTreeClass::Control_Bone(int boneindex, const Matrix3D &relative_tm, bool world_space_translation)
{
	_STL::vector<HTreeCapture>::iterator capture = CaptureList.begin();
	while (capture != CaptureList.end() && capture->BoneIndex < boneindex) {
		capture++;
	}
	if (capture != CaptureList.end() && capture->BoneIndex == boneindex) {
		capture->WorldSpaceTranslation = world_space_translation;
		capture->Transform.Rotation = Build_Quaternion(relative_tm);
		capture->Transform.Translation.X = relative_tm[0][3];
		capture->Transform.Translation.Y = relative_tm[1][3];
		capture->Transform.Translation.Z = relative_tm[2][3];
	}
}

