// FUNCTION: BFME2 0x001622B0 size=1335 name=?Capture_Update@HTreeClass@@QAEHH@Z evidence=N:ledger tier=B hypothesis:K
int HTreeClass::Capture_Update(int pivot_index)
{
	_STL::vector<HTreeCapture>::iterator i;
	for (i = CaptureList.begin(); i != CaptureList.end() && i->BoneIndex < pivot_index; ++i) {
	}

	if (i == CaptureList.end() || i->BoneIndex != pivot_index) {
		return -1;
	}

	if (i->WorldSpaceTranslation) {
		PivotTransform rotation(i->Transform.Rotation, Vector3(0.0f, 0.0f, 0.0f));
		Pivot[pivot_index].Current.PostMul(rotation);
		Pivot[pivot_index].Current.Translation += i->Transform.Translation;
	} else {
		Pivot[pivot_index].Current.PostMul(i->Transform);
	}

	++i;
	if (i == CaptureList.end()) {
		return -1;
	}
	return i->BoneIndex;
}


